/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// Find method for METCardTypeTable
/// </summary>
/// <param name="_cardType">CardType value (EDT METCardType)</param>
/// <param name="_forUpdate">Optional: true if record should be selected for update</param>
/// <returns>METCardTypeTable record</returns>
public static METCardTypeTable find(METCardType _cardType, boolean _forUpdate = false)
{
    METCardTypeTable metCardTypeTable;

    if (_cardType)
    {
        if (_forUpdate)
        {
            metCardTypeTable.selectForUpdate(_forUpdate);
        }

        select firstonly metCardTypeTable
        where metCardTypeTable.CardType == _cardType;
    }

    return metCardTypeTable;
}

/// <summary>
/// Checks if a record exists in METCardTypeTable for the given CardType.
/// </summary>
/// <param name="_cardType">CardType value (EDT METCardType)</param>
/// <returns>True if record exists, otherwise false</returns>
public static boolean exist(METCardType _cardType)
{
    return _cardType &&
       (select firstonly RecId from METCardTypeTable
            where METCardTypeTable.CardType == _cardType).RecId != 0;
}
